-- ============================================================
-- league_data_nba.sql — NBA 真实数据入库（由 scripts_cloudbase/build-nba-db.py 生成）
-- 数据源：腾讯体育（data/nba.json）· 赛程比分页 NBA 段（data/matches.json）
-- 前置：db/migrate-day22-league-season.sql（season / zone 列）+ db/league_data.sql
-- 可重复执行：先清空 league_id=nba / league=NBA 的行，再插入
-- 规模：league_schedule 1826 · league_standings 30 · league_brackets 2 · matches 13
-- ============================================================

BEGIN;

-- ---------- 1. 联赛维度表（与真实数据的 desc / tabs 对齐）----------
-- 用 upsert：维度表已有 nba 这一行，重跑不该报主键冲突
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, sport = EXCLUDED.sport,
  emoji = EXCLUDED.emoji, description = EXCLUDED.description,
  tabs = EXCLUDED.tabs, updated_at = EXCLUDED.updated_at;

-- ---------- 2. 清空 NBA 旧数据 ----------
DELETE FROM public.league_schedule WHERE league_id = 'nba';
DELETE FROM public.league_standings WHERE league_id = 'nba';
DELETE FROM public.league_players WHERE league_id = 'nba';
DELETE FROM public.league_brackets WHERE league_id = 'nba';
DELETE FROM public.matches WHERE league = 'NBA';

-- ---------- 3. league_schedule（两个赛季 1826 场）----------

-- ---------- 4. league_standings（25-26 东西部各 15 队）----------

-- ---------- 5. league_brackets（晋级图 + 季后赛对阵）----------

-- ---------- 6. matches（赛程比分页 NBA 段 13 条）----------

COMMIT;

-- 收尾自检
SELECT 'league_schedule' t, count(*) FROM public.league_schedule WHERE league_id='nba'
UNION ALL SELECT 'league_standings', count(*) FROM public.league_standings WHERE league_id='nba'
UNION ALL SELECT 'league_brackets',  count(*) FROM public.league_brackets  WHERE league_id='nba'
UNION ALL SELECT 'matches(NBA)',     count(*) FROM public.matches        WHERE league='NBA';
SELECT season, count(*) FROM public.league_schedule WHERE league_id='nba' GROUP BY season ORDER BY season;
SELECT season, zone, count(*) FROM public.league_standings WHERE league_id='nba' GROUP BY season, zone ORDER BY season, zone;
